#include "kernel/param.h"
#include "kernel/types.h"
#include "user/user.h"

/* get prefix
 *
 * line = ''
 * while (readchar() is not EOF):
 *   if char is newline:
 *     process(line)
 *     line = ''  // reset
 *   else:
 *     append char to line
 *
 *   if line is non-empty: // in case input doesn't terminate in newline
 *     process(line)
 *
 *  process(line):
 *    fork()
 *    in child: exec with args from line // MAXARGS maybe relevant
 *    in parent: wait
 *
 *    edge case:
 *      - empty input
 *      - input doesn't terminate in newline
 *      - commands generated by xargs exit non-zero  -- seems unix xargs is ok
 * with this, still exits zero, stderr is not inserted into template, just
 * printed as usual
 *
 */

char **split(char *line) {
  // TODO: what about trailing newline?
  int line_idx, words_idx;
  char *word_start;
  char **words = malloc(
      MAXARG * sizeof(char *)); // TODO: should be MAXARG - length of argv?

  words_idx = 0;
  word_start = line;
  for (line_idx = 0;; line_idx++) {
    if (*(line + line_idx) == ' ' || *(line + line_idx) == '\0') {
      // We've hit the end of a word.
      *(line + line_idx) = '\0'; // So the word can be used as its own string.
      words[words_idx] = word_start;
      word_start = line + line_idx + 1;
      words_idx++;
    }
    if (*(line + line_idx) == '\0') {
      words[words_idx] = 0;
      break;
    }
  }

  return words;
}

int readline(int fd, char *line) {
  int count = 0;
  int num_read;
  int ret;

  while (1) {
    num_read = read(fd, line + count, 1);
    if (num_read == 0) {
      ret = 0;
      break;
    }
    if (line[count] == '\n') {
      line[count] = '\0';
      ret = 1;
      break;
    }
    count++;
  }

  return ret; // number of lines read, maybe 0
}
int main(int argc, char *argv[]) {
  char **suffix;
  char input_line[100]; // TODO: what should max size be?
  char *command[200];
  int i, j;

  while (readline(0, input_line) == 1) {
    // We read a line.
    // Split on whitespace into words.
    suffix = split(input_line);

    // Build up complete command, by concatenating argv[1:] and suffix.
    for (i = 1; i < argc; i++) {
      command[i - 1] = argv[i];
    }

    for (j = 0;; j++) {
      if (suffix[j] == 0) {
        break;
      }
      command[i - 1 + j] = suffix[j];
    }

    // Fork, exec, wait.
    if (fork() == 0) {
      exec("echo", command);
    } else {
      wait(0);
    }
  }
}
